def find_nth_element(n):
    s = [1, 2, 3, 4]
    while len(s) < n:
        x = s[-1]
        y = s[-2]
        z = s[-3]
        a = x ^ y ^ z
        s.append(a)
        s.sort()
    return s[n - 1]

def main():
    t = int(input())
    results = []
    for _ in range(t):
        n = int(input())
        results.append(find_nth_element(n))
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
